SELECT length('0x1F'), upper('0x1F'), lower('0x1F'), substr('0x1F', 0, 0), instr('0x1F', 'a%b'), replace('0x1F', '', ''), trim('0x1F'), ltrim('0x1F', 'ab'), hex('0x1F'), quote('0x1F'), unicode('0x1F'), '0x1F' LIKE '%a_', '0x1F' GLOB '*', char(69, 562), '0x1F' || 'a%b', '0x1F' < 'a%b', '0x1F' = 'a%b' COLLATE NOCASE;
SELECT length('theta'), upper('theta'), lower('theta'), substr('theta', 2, 3), instr('theta', 'tau'), replace('theta', '', 'XY'), trim('theta'), ltrim('theta', 'ab'), hex('theta'), quote('theta'), unicode('theta'), 'theta' LIKE '_', 'theta' GLOB 'a*', char(66, 871), 'theta' || 'tau', 'theta' < 'tau', 'theta' = 'tau' COLLATE NOCASE;
SELECT length('chi'), upper('chi'), lower('chi'), substr('chi', 2, 4), instr('chi', 'café'), replace('chi', 'é', ''), trim('chi'), ltrim('chi', 'ab'), hex('chi'), quote('chi'), unicode('chi'), 'chi' LIKE '%', 'chi' GLOB '*[a-m]*', char(75, 493), 'chi' || 'café', 'chi' < 'café', 'chi' = 'café' COLLATE NOCASE;
SELECT length('chi'), upper('chi'), lower('chi'), substr('chi', 4, 4), instr('chi', 'it''s'), replace('chi', 'e', ''), trim('chi'), ltrim('chi', 'ab'), hex('chi'), quote('chi'), unicode('chi'), 'chi' LIKE '%a_', 'chi' GLOB '?', char(83, 723), 'chi' || 'it''s', 'chi' < 'it''s', 'chi' = 'it''s' COLLATE NOCASE;
SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', -1, 3), instr('phi', 'pi'), replace('phi', 'a', 'XY'), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE '_', 'phi' GLOB '?', char(81, 679), 'phi' || 'pi', 'phi' < 'pi', 'phi' = 'pi' COLLATE NOCASE;
SELECT length('eta'), upper('eta'), lower('eta'), substr('eta', 4, 0), instr('eta', 'tau'), replace('eta', 'e', ''), trim('eta'), ltrim('eta', 'ab'), hex('eta'), quote('eta'), unicode('eta'), 'eta' LIKE '_', 'eta' GLOB '?', char(69, 552), 'eta' || 'tau', 'eta' < 'tau', 'eta' = 'tau' COLLATE NOCASE;
