SELECT json_valid('[1,"two",3.0,true,false,null,{"k":"v"}]'), json('[1,"two",3.0,true,false,null,{"k":"v"}]'), json_type('[1,"two",3.0,true,false,null,{"k":"v"}]'), json_array_length('[1,"two",3.0,true,false,null,{"k":"v"}]'), json_extract('[1,"two",3.0,true,false,null,{"k":"v"}]', '$.a', '$[1]', '$.b[2].c'), '[1,"two",3.0,true,false,null,{"k":"v"}]' -> '$.b', '[1,"two",3.0,true,false,null,{"k":"v"}]' ->> '$.n.m.o';
SELECT key, value, type FROM json_each('[1,"two",3.0,true,false,null,{"k":"v"}]') ORDER BY key;
SELECT json_set('[1,"two",3.0,true,false,null,{"k":"v"}]', '$.z', 1), json_insert('[1,"two",3.0,true,false,null,{"k":"v"}]', '$.a', 2), json_remove('[1,"two",3.0,true,false,null,{"k":"v"}]', '$.a'), json_patch('{"a":1}', '{"b":2}');
SELECT json_group_array(id), json_group_object(CAST(id AS TEXT), c0) FROM t0;
SELECT json_object('id', id, 'v', c1) FROM t0 ORDER BY id LIMIT 4;
